//go:build integration

package integration

import (
	"os"
	"path/filepath"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
	"github.com/stretchr/testify/require"
)

// TestCodexSubagent_StoresDeclaredSubagentTranscript drives Codex's subagent hooks
// end to end — subagent-start → the subagent edits a file → subagent-stop → commit —
// and asserts the declared rollout reaches the condensed checkpoint's tasks/ subtree
// via the task record the materializer follows (#2058).
//
// The rollout path here is deliberately flat, matching Codex's real layout and
// matching neither candidate the Claude Code fallback probes, so the assertion can
// only pass if the declared path is honoured (see Event.SubagentTranscriptPath).
func TestCodexSubagent_StoresDeclaredSubagentTranscript(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)

	const (
		sessionID  = "test-codex-subagent"
		agentID    = "child-thread-9"
		editedFile = "docs/red.md"
	)

	require.NoError(t, env.WriteSessionState(sessionID, &session.State{
		SessionID:  sessionID,
		AgentType:  agent.AgentTypeCodex,
		BaseCommit: env.GetHeadHash(),
	}))

	rolloutDir := filepath.Join(env.RepoDir, ".entire", "tmp", "codex-rollouts")
	require.NoError(t, os.MkdirAll(rolloutDir, 0o750))
	parentRollout := filepath.Join(rolloutDir, "rollout-"+sessionID+".jsonl")
	require.NoError(t, os.WriteFile(parentRollout, []byte(`{"type":"session_meta","payload":{"id":"`+sessionID+`"}}`+"\n"), 0o600))
	subagentRollout := filepath.Join(rolloutDir, "rollout-"+agentID+".jsonl")
	require.NoError(t, os.WriteFile(subagentRollout,
		[]byte(`{"type":"response_item","payload":{"content":"wrote `+editedFile+`"}}`+"\n"), 0o600))

	hook := codexHooker(t, env.RepoDir, sessionID, parentRollout)
	hook("subagent-start", map[string]any{
		"hook_event_name": "SubagentStart",
		"agent_id":        agentID,
		"agent_type":      "reviewer",
		"turn_id":         "turn-1",
	})

	env.WriteFile(editedFile, "Red is a warm colour.\n")

	hook("subagent-stop", map[string]any{
		"hook_event_name":       "SubagentStop",
		"agent_id":              agentID,
		"agent_type":            "reviewer",
		"agent_transcript_path": subagentRollout,
		"stop_hook_active":      false,
		"turn_id":               "turn-1",
	})

	// Codex sends no tool_use_id, so agent_id is the correlation key and therefore
	// keys the task record.
	state, err := env.GetSessionState(sessionID)
	require.NoError(t, err)
	rec := state.FindTaskRecord(agentID)
	require.NotNil(t, rec, "expected a task record keyed by agent_id")
	require.False(t, rec.CompletedAt.IsZero(), "subagent-stop must complete the record")
	require.Equal(t, subagentRollout, rec.DeclaredTranscriptPath,
		"the declared agent_transcript_path was not honoured")
	require.True(t, containsFile(rec.Files, editedFile),
		"the record must carry the subagent's edit, got %v", rec.Files)

	// Committing condenses the session, and the materializer must store the rollout
	// itself — the storage guarantee this test is named for.
	env.GitCommitWithShadowHooksAsAgent("Add red doc", editedFile)
	checkpointID := env.TryGetLatestCheckpointID()
	require.NotEmpty(t, checkpointID, "expected a condensed checkpoint after committing the subagent's work")
	stored, ok := env.ReadFileFromBranch(paths.MetadataBranchName,
		CheckpointTaskFilePath(checkpointID, agentID, paths.AgentTranscriptFileName(agentID)))
	require.True(t, ok, "declared rollout not materialized under the checkpoint's tasks/ subtree")
	require.Contains(t, stored, editedFile, "materialized transcript is not the subagent's rollout")
}
//go:build integration

package integration

import (
	"strings"
	"testing"

	"github.com/entireio/cli/cmd/entire/cli/paths"
	"github.com/entireio/cli/cmd/entire/cli/session"
)

// REDACTED reproduces the
// orphaned shadow branch behind the e2e failure of
// TestSingleSessionSubagentCommitInTurn.
//
// The subagent writes a file and commits it itself, mid-turn. That commit condenses
// the session and deletes the shadow branch. post-task then fires with nothing left
// to snapshot — the file is already in HEAD — so it must skip the task checkpoint.
// Creating one instead mints a *new* shadow branch after condensation has already
// run, and nothing ever condenses it away: turn-end sees no file modifications and
// skips, so the branch outlives the session.
//
// The trap is that the subagent's transcript still records the Write. Deciding from
// the transcript alone conflates "the subagent wrote this at some point" with "there
// is an uncommitted change here" — see filterToUncommittedFiles, which the turn-end
// path already applies for exactly this reason.
func REDACTED(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)
	session := env.NewSession()
	session.CreateTranscript("use a subagent to write docs/red.md and commit it", nil)

	const (
		taskToolUseID = "toolu_01CommitInTurn"
		subagentID    = "a0011223344556677"
		editedFile    = "docs/red.md"
	)
	// The subagent's own transcript records the Write; the main transcript does not.
	session.CreateSubagentTranscript(subagentID, []FileChange{{Path: editedFile, Content: "Red is warm.\n"}})

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}
	if err := env.SimulatePreTask(session.ID, session.TranscriptPath, taskToolUseID); err != nil {
		t.Fatalf("SimulatePreTask failed: %v", err)
	}

	// The subagent writes the file and commits it itself, still inside the turn.
	env.WriteFile(editedFile, "Red is a warm colour.\n")
	env.GitCommitWithShadowHooksAsAgent("Add red.md", editedFile)

	// Condensation ran on that commit and cleaned up the shadow branch.
	if got := shadowBranches(env); len(got) != 0 {
		t.Fatalf("precondition: shadow branch should be gone after the mid-turn commit, got %v", got)
	}

	if err := env.SimulatePostTask(PostTaskInput{
		SessionID:      session.ID,
		TranscriptPath: session.TranscriptPath,
		ToolUseID:      taskToolUseID,
		AgentID:        subagentID,
	}); err != nil {
		t.Fatalf("SimulatePostTask failed: %v", err)
	}

	if got := shadowBranches(env); len(got) != 0 {
		t.Errorf("post-task created a shadow branch for already-committed work: %v\n"+
			"nothing will condense it away — turn-end skips when no files changed", got)
	}
}

// TestSubagentCheckpoints_UncommittedWork_StillCheckpoints is the companion guard:
// filtering already-committed paths must not stop a subagent whose work is still
// uncommitted from getting its task checkpoint.
func TestSubagentCheckpoints_UncommittedWork_StillCheckpoints(t *testing.T) {
	t.Parallel()
	env := NewFeatureBranchEnv(t)
	session := env.NewSession()
	session.CreateTranscript("use a subagent to write docs/blue.md", nil)

	const (
		taskToolUseID = "toolu_01UncommittedWork"
		subagentID    = "a7766554433221100"
		editedFile    = "docs/blue.md"
	)
	session.CreateSubagentTranscript(subagentID, []FileChange{{Path: editedFile, Content: "Blue is cool.\n"}})

	if err := env.SimulateUserPromptSubmit(session.ID); err != nil {
		t.Fatalf("SimulateUserPromptSubmit failed: %v", err)
	}
	if err := env.SimulatePreTask(session.ID, session.TranscriptPath, taskToolUseID); err != nil {
		t.Fatalf("SimulatePreTask failed: %v", err)
	}

	// Left uncommitted, unlike the test above.
	env.WriteFile(editedFile, "Blue is a cool colour.\n")

	if err := env.SimulatePostTask(PostTaskInput{
		SessionID:      session.ID,
		TranscriptPath: session.TranscriptPath,
		ToolUseID:      taskToolUseID,
		AgentID:        subagentID,
	}); err != nil {
		t.Fatalf("SimulatePostTask failed: %v", err)
	}

	state, err := env.GetSessionState(session.ID)
	if err != nil {
